import type { PalavraHebraica } from '@/data/lexicon/hebraico';
import type { PalavraGrega } from '@/data/lexicon/grego';

let _hebLookup: Record<string, PalavraHebraica> | null = null;
let _grkLookup: Record<string, PalavraGrega> | null = null;
let _hebPromise: Promise<typeof import('@/data/lexicon/hebraico')> | null = null;
let _grkPromise: Promise<typeof import('@/data/lexicon/grego')> | null = null;

async function loadHebraico() {
  if (!_hebPromise) _hebPromise = import('@/data/lexicon/hebraico');
  return _hebPromise;
}

async function loadGrego() {
  if (!_grkPromise) _grkPromise = import('@/data/lexicon/grego');
  return _grkPromise;
}

async function getHebLookup() {
  if (!_hebLookup) {
    const mod = await loadHebraico();
    _hebLookup = {};
    for (const p of mod.palavrasHebraicas) _hebLookup[p.strong] = p;
  }
  return _hebLookup;
}

async function getGrkLookup() {
  if (!_grkLookup) {
    const mod = await loadGrego();
    _grkLookup = {};
    for (const p of mod.palavrasGregas) _grkLookup[p.strong] = p;
  }
  return _grkLookup;
}

export async function getStrongPorVersiculo(livro: string, capitulo: number, versiculo: number): Promise<PalavraStrong[]> {
  const key = `${livro}:${capitulo}:${versiculo}`;
  const entry = STRONG_CODES[key];
  if (!entry) return [];
  const [codes, morphs] = entry;
  const heb = await getHebLookup();
  const grk = await getGrkLookup();
  return codes.map((code, i) => {
    const isHeb = code.startsWith('H');
    const lex = isHeb ? heb[code] : grk[code];
    return {
      strong: code,
      palavra: lex?.palavra || '',
      transliteracao: lex?.transliteracao || '',
      definicao: lex?.definicao || '',
      morfologia: morphs[i] || '',
      idioma: isHeb ? 'hebraico' : 'grego',
    };
  });
}

export async function buscarVersiculoComStrong(livro: string, capitulo: number, versiculo: number): Promise<PalavraStrong[]> {
  return getStrongPorVersiculo(livro, capitulo, versiculo);
}

export async function buscarPalavraStrong(codigo: string): Promise<PalavraStrong | null> {
  const isHeb = codigo.startsWith('H');
  const lex = isHeb ? (await getHebLookup())[codigo] : (await getGrkLookup())[codigo];
  if (!lex) return null;
  return {
    strong: codigo,
    palavra: lex.palavra,
    transliteracao: lex.transliteracao,
    definicao: lex.definicao,
    morfologia: '',
    idioma: isHeb ? 'hebraico' : 'grego',
  };
}

export function getVersiculosComStrong(): string[] {
  return Object.keys(STRONG_CODES);
}

export async function getStrongPorChave(key: string): Promise<PalavraStrong[]> {
  const entry = STRONG_CODES[key];
  if (!entry) return [];
  const [codes, morphs] = entry;
  const heb = await getHebLookup();
  const grk = await getGrkLookup();
  return codes.map((code, i) => {
    const isHeb = code.startsWith('H');
    const lex = isHeb ? heb[code] : grk[code];
    return {
      strong: code,
      palavra: lex?.palavra || '',
      transliteracao: lex?.transliteracao || '',
      definicao: lex?.definicao || '',
      morfologia: morphs[i] || '',
      idioma: isHeb ? 'hebraico' : 'grego',
    };
  });
}

export async function buscarStrong(termo: string): Promise<PalavraStrong[]> {
  const termoLower = termo.toLowerCase();
  const results: PalavraStrong[] = []
  const heb = await getHebLookup();
  const grk = await getGrkLookup();
  if (termo.startsWith('H') || termo.startsWith('G')) {
    const lex = termo.startsWith('H') ? heb[termo] : grk[termo];
    if (lex) {
      results.push({ strong: termo, palavra: lex.palavra, transliteracao: lex.transliteracao, definicao: lex.definicao, morfologia: '', idioma: termo.startsWith('H') ? 'hebraico' : 'grego' });
    }
  } else {
    for (const [code, entry] of Object.entries(heb)) {
      if (entry.palavra.toLowerCase().includes(termoLower) || entry.transliteracao.toLowerCase().includes(termoLower)) {
        results.push({ strong: code, palavra: entry.palavra, transliteracao: entry.transliteracao, definicao: entry.definicao, morfologia: '', idioma: 'hebraico' });
      }
    }
    for (const [code, entry] of Object.entries(grk)) {
      if (entry.palavra.toLowerCase().includes(termoLower) || entry.transliteracao.toLowerCase().includes(termoLower)) {
        results.push({ strong: code, palavra: entry.palavra, transliteracao: entry.transliteracao, definicao: entry.definicao, morfologia: '', idioma: 'grego' });
      }
    }
  }
  return results;
}

export function getTodasOcorrenciasStrong(codigo: string): string[] {
  const results: string[] = []
  for (const [key, [codes]] of Object.entries(STRONG_CODES)) {
    if (codes.includes(codigo)) results.push(key);
  }
  return results;
}

export interface OcorrenciaCorpus {
  ref: string;
  strong: string;
  palavra: string;
  transliteracao: string;
  definicao: string;
  morfologia: string;
  idioma: 'grego' | 'hebraico';
}

export interface FiltroMorfologico {
  /** Restringe a busca a um idioma. Se omitido, busca em ambos. */
  idioma?: 'grego' | 'hebraico';
  /**
   * Lista de termos que devem aparecer (todos, lógica E) no rótulo morfológico
   * de cada palavra do corpus (comparação case-insensitive). Ex.: ['aoristo', 'passivo', 'indicativo'].
   */
  morfologiaContem?: string[];
}

/**
 * Busca real no corpus interlinear (STRONG_CODES, ~31 mil versículos) por um
 * padrão gramatical/morfológico — não uma busca no léxico (que é um dicionário
 * de lemas), mas nas ocorrências de fato marcadas em cada versículo.
 *
 * Ex.: buscarPadraoMorfologico({ idioma: 'grego', morfologiaContem: ['aoristo', 'passivo', 'indicativo'] })
 *      retorna todos os aoristos passivos indicativos atestados no corpus.
 */
export async function buscarPadraoMorfologico(
  filtro: FiltroMorfologico,
  limite = 300
): Promise<{ total: number; ocorrencias: OcorrenciaCorpus[] }> {
  const termos = (filtro.morfologiaContem ?? []).map((t) => t.toLowerCase());
  const heb = await getHebLookup();
  const grk = await getGrkLookup();
  const ocorrencias: OcorrenciaCorpus[] = [];
  let total = 0;

  for (const [ref, [codes, morphs]] of Object.entries(STRONG_CODES)) {
    for (let i = 0; i < codes.length; i++) {
      const code = codes[i];
      const isHeb = code.startsWith('H');
      const idioma: 'grego' | 'hebraico' = isHeb ? 'hebraico' : 'grego';
      if (filtro.idioma && filtro.idioma !== idioma) continue;

      const morfBruta = morphs[i] || '';
      if (termos.length > 0) {
        const morfLower = morfBruta.toLowerCase();
        if (!termos.every((termo) => morfLower.includes(termo))) continue;
      }

      total++;
      if (ocorrencias.length < limite) {
        const lex = isHeb ? heb[code] : grk[code];
        ocorrencias.push({
          ref,
          strong: code,
          palavra: lex?.palavra || '',
          transliteracao: lex?.transliteracao || '',
          definicao: lex?.definicao || '',
          morfologia: morfBruta,
          idioma,
        });
      }
    }
  }

  return { total, ocorrencias };
}


export function ehCodigoStrongValido(codigo: string): boolean {
  return /^[HG]\d+$/.test(codigo);
}

const cacheOcorrenciasLivro = new Map<string, Map<string, string[]>>();

/** Versículos únicos por Strong neste livro (mesma regra de getTodasOcorrenciasStrong). */
export function ocorrenciasPorStrongNoLivro(livro: string): Map<string, string[]> {
  const key = livro.toLowerCase();
  const hit = cacheOcorrenciasLivro.get(key);
  if (hit) return hit;
  const prefix = `${key}:`;
  const map = new Map<string, string[]>();
  for (const [ref, [codes]] of Object.entries(STRONG_CODES)) {
    if (!ref.startsWith(prefix)) continue;
    const noVerso = new Set<string>();
    for (const code of codes) {
      if (!ehCodigoStrongValido(code) || noVerso.has(code)) continue;
      noVerso.add(code);
      const arr = map.get(code);
      if (arr) arr.push(ref);
      else map.set(code, [ref]);
    }
  }
  cacheOcorrenciasLivro.set(key, map);
  return map;
}

export function getCoberturaStrongDoLivro(livro: string): {
  capitulosComStrong: number;
  versiculosComStrong: number;
} {
  const prefix = `${livro.toLowerCase()}:`;
  const caps = new Set<number>();
  let versiculosComStrong = 0;
  for (const ref of Object.keys(STRONG_CODES)) {
    if (!ref.startsWith(prefix)) continue;
    versiculosComStrong++;
    const cap = Number(ref.split(':')[1]);
    if (Number.isFinite(cap)) caps.add(cap);
  }
  return { capitulosComStrong: caps.size, versiculosComStrong };
}

export interface PalavraRaraNoLivro {
  strong: string;
  noLivro: number;
  versiculosNoLivro: string[];
  versiculosNoCapitulo: string[];
}

/**
 * Lemas deste capítulo cujo Strong ocorre 1× ou 2× (versículos únicos) neste livro.
 * Hapax / quase-hapax de livro — não da Bíblia inteira.
 */
export function getPalavrasRarasNoCapitulo(
  livro: string,
  capitulo: number,
  maxNoLivro = 2
): PalavraRaraNoLivro[] {
  const freq = ocorrenciasPorStrongNoLivro(livro);
  const prefixCap = `${livro.toLowerCase()}:${capitulo}:`;
  const out: PalavraRaraNoLivro[] = [];
  for (const [strong, refs] of freq) {
    if (refs.length < 1 || refs.length > maxNoLivro) continue;
    const versiculosNoCapitulo = refs.filter((r) => r.startsWith(prefixCap));
    if (versiculosNoCapitulo.length === 0) continue;
    out.push({
      strong,
      noLivro: refs.length,
      versiculosNoLivro: refs,
      versiculosNoCapitulo,
    });
  }
  out.sort((a, b) => a.noLivro - b.noLivro || a.strong.localeCompare(b.strong, 'en'));
  return out;
}
